'use strict';
// Coach marks leave actual game controls in place: no copied cards or simulated purchases.
const TutorialText={
 'return-info':['Undo an accidental deployment','Desfaça uma colocação acidental','During setup, select a unit and use Return to hand, or drag it back to the hand. You recover all energy paid. Only units played this round after the last hand refresh qualify; the hand needs a free slot. Starting combat or refreshing the hand ends eligibility. Returning a fusion undoes its latest eligible copy.','Durante o preparo, selecione a unidade e use Voltar à mão, ou arraste-a para a mão. Toda a energia paga é devolvida. Só vale para unidades jogadas nesta rodada após a última reciclagem, com espaço na mão. Combater ou reciclar encerra essa possibilidade. Em uma fusão, volta a última cópia elegível.'],
 'select-warrior':['Select Warrior','Selecione Warrior','Tap the highlighted card. Its energy cost appears in the upper corner. You can also drag it to the highlighted field position.','Toque na carta destacada. O custo de energia fica no canto superior. Você também pode arrastá-la para a posição destacada no campo.'],
 'place-warrior':['Place your first unit','Posicione a primeira unidade','Tap the highlighted field position. You pay energy when the unit enters the field or reserve.','Toque na posição destacada no campo. A energia é paga ao colocar a unidade no campo ou no banco.'],
 traits:['Traits and synergies','Traits e sinergias','The counters show your team traits. Different characters activate bonuses at 2 and 3. Selecting or dragging a card previews the result; identical copies do not add another trait count.','Os contadores mostram os traits da equipe. Personagens diferentes ativam bônus com 2 e 3. Selecionar ou arrastar uma carta mostra a prévia; cópias iguais não somam outra contagem.'],
 'select-lancer':['Choose a partner','Escolha uma parceira','Select Lancer. Preview the highlighted traits, then place her beside Warrior.','Selecione Lancer. Confira os traits destacados e depois posicione-a ao lado de Warrior.'],
 'place-lancer':['Complete the formation','Complete a formação','Place Lancer in the highlighted position. Tap or drag: both work.','Coloque Lancer na posição destacada. Pode tocar ou arrastar.'],
 energy:['Energy and unit limit','Energia e limite de unidades','You started with 5 energy and spent 4. Unspent energy carries over. Round 1 allows 2 units; each new round adds a slot, up to 6.','Você começou com 5 de energia e gastou 4. O saldo acumula. A rodada 1 permite 2 unidades; cada nova rodada acrescenta uma vaga, até 6.'],
 fight:['Start the battle','Comece a batalha','Your formation is ready. Tap Battle to face this fixed training opponent.','Sua formação está pronta. Toque em Combater para enfrentar este adversário de aprendizado.'],
 combat:['Automatic combat and skills','Combate automático e skills','Units move and attack automatically. The bar above each unit charges its skill; each character has a trigger. The battle is paused while you read.','As unidades se movem e atacam sozinhas. A barra acima de cada unidade carrega sua skill; cada personagem tem um gatilho. A batalha está pausada enquanto você lê.'],
 speed:['Control the speed','Controle a velocidade','Choose ×1.5, ×2 or ×3 to resume and watch the battle faster. You can pause with the button at the bottom.','Escolha ×1,5, ×2 ou ×3 para retomar e acelerar a batalha. O botão na parte inferior permite pausar.'],
 watch:['Watch your team','Observe sua equipe','Combat is automatic. You can change speed or pause. After this round, we will use the reserve and freeze the hand.','O combate é automático. Você pode mudar a velocidade ou pausar. Depois desta rodada, vamos usar o banco e congelar a mão.'],
 result:['Prepare the next round','Prepare a próxima rodada','The score tracks round wins. Normal encounters end at 3 wins; the Boss at 4. Tap Prepare round 2.','O placar registra as vitórias em rodadas. Confrontos normais acabam com 3 vitórias; o Boss, com 4. Toque em Preparar rodada 2.'],
 'select-reserve':['Keep a unit in reserve','Guarde uma unidade no banco','Round 2 grants 4 energy plus your leftover balance. Select Fighter to buy him into the reserve.','A rodada 2 concede 4 de energia, além do saldo anterior. Selecione Fighter para colocá-lo no banco.'],
 'place-reserve':['Use the reserve','Use o banco','Place Fighter in the highlighted reserve slot. The reserve has 6 slots; buying a unit here costs the same energy as placing it on the field.','Coloque Fighter na vaga destacada do banco. Há 6 vagas; comprar aqui custa a mesma energia que colocar no campo.'],
 'select-bench':['Bring the reserve to the field','Leve o banco para o campo','Select Fighter in the reserve, or drag him to the highlighted field position. Moving an already purchased unit is free.','Selecione Fighter no banco ou arraste-o para a posição destacada no campo. Mover uma unidade já comprada é grátis.'],
 transfer:['Move without spending energy','Mova sem gastar energia','Tap the highlighted field position. Round 2 now allows 3 units.','Toque na posição destacada do campo. A rodada 2 já permite 3 unidades.'],
 freeze:['Preserve the remaining hand','Preserve o restante da mão','Tap ❄ Freeze. These cards stay for the next round, which draws only enough to fill the hand to 4. Freezing costs no energy and is optional during normal play.','Toque em ❄ Congelar. Estas cartas ficam para a próxima rodada, que compra apenas o necessário para completar 4. Congelar não custa energia e é opcional no jogo normal.'],
 complete:['First steps complete','Primeiros passos concluídos','You learned formation, traits, energy, combat, reserve and hand freeze. Finish to unlock two more borrowed decks. Three paid copies fuse automatically; we will point it out when an opportunity appears.','Você aprendeu formação, traits, energia, combate, banco e congelamento. Conclua para liberar mais dois baralhos emprestados. Três cópias pagas se fundem automaticamente; avisaremos quando surgir uma oportunidade.']
};
Object.assign(TutorialText,{
 'select-bench':['Drag from reserve','Arraste do banco','Drag Fighter from the reserve onto the highlighted field slot. The aim above the card shows where it will land; traits preview while dragging. Moving costs no energy.','Arraste Fighter do banco até a vaga destacada no campo. A mira acima da carta indica o destino; os traits mostram a prévia durante o arraste. Mover não custa energia.'],
 transfer:['Practice dragging','Pratique o arraste','Hold and drag Fighter to the highlighted field slot. Release when the aim highlights the destination.','Segure e arraste Fighter até a vaga destacada. Solte quando a mira destacar o destino.'],
 'drag-again':['Try a move','Experimente mover','Drag Fighter to another empty field slot to practice the aim.','Arraste Fighter até outra vaga vazia no campo para praticar a mira.'],
 'remove-select':['Recover energy','Recupere energia','Select Fighter on the field. You can remove a paid unit to recover half its energy cost, rounded down.','Selecione Fighter no campo. Você pode retirar uma unidade paga para recuperar metade do custo de energia, arredondada para baixo.'],
 'remove-unit':['Check the refund','Confira a devolução','The trash button shows the energy refund. Use it now: Fighter goes to the discard pile and remains in your run deck.','O botão da lixeira informa a energia devolvida. Use agora: Fighter vai para o descarte e continua no deck da run.'],
 removed:['Card preserved','Carta preservada','Removing a unit does not delete its card from your deck. It can be drawn again. Permanently removing a card is a separate service in a run shop.','Retirar uma unidade não apaga sua carta do deck. Ela pode voltar à mão. Remover uma carta do deck é um serviço separado na loja da run.'],
 refresh:['Refresh the hand','Recicle a mão','Tap ↻. Spend 1 energy to discard this hand and draw up to 4 cards. This does not refund energy from deployed units.','Toque em ↻. Gaste 1 de energia para descartar esta mão e comprar até 4 cartas. Isso não devolve energia das unidades posicionadas.'],
 'inspect-select':['Inspect a character','Inspecione um personagem','Select a card, then use its information button. In normal play, you can also hold a card to inspect it.','Selecione uma carta e use o botão de informações. No jogo normal, você também pode segurar uma carta para inspecionar.'],
 inspect:['Open the details','Abra os detalhes','Tap the information button beside the selected character.','Toque no botão de informações ao lado do personagem selecionado.'],
 'inspect-read':['Stats, range and skill','Atributos, alcance e skill','Inspect the stats, range, traits and skill trigger. Frontline units protect ranged units; units normally seek the closest enemy.','Confira atributos, alcance, traits e gatilho da skill. Unidades da frente protegem as de longo alcance; normalmente buscam o inimigo mais próximo.'],
 deck:['View the run deck','Veja o deck da run','Open View deck to see every card in this run, including its independent copies and upgrades.','Abra Ver deck para consultar todas as cartas desta run, incluindo cópias independentes e upgrades.'],
 'deck-read':['Your complete run deck','Seu deck completo da run','These are all your run cards, including cards in hand, draw, discard, field, reserve and fusion. Collection ownership is separate.','Aqui estão todas as cartas da run, incluindo mão, compra, descarte, campo, banco e fusão. A coleção permanente é separada.'],
 piles:['Follow the card cycle','Acompanhe o ciclo das cartas','Open the card cycle button beside View deck to see where your cards are.','Abra o botão de ciclo das cartas ao lado de Ver deck para consultar onde elas estão.'],
 'piles-read':['Every card has a place','Cada carta tem seu lugar','When draw runs out, discard is shuffled. Paid units keep their cards bound outside the draw pile; a fusion binds all 3 original cards.','Quando a compra acaba, o descarte é reembaralhado. Unidades pagas mantêm suas cartas vinculadas fora da compra; uma fusão vincula as 3 cartas originais.'],
 'second-copy':['Prepare a fusion','Prepare uma fusão','Buy another Warrior into the reserve. It costs 2 energy. Your first Warrior is already on the field; identical copies do not add trait counts.','Compre outro Warrior no banco. Custa 2 de energia. Seu primeiro Warrior já está no campo; cópias iguais não somam contagem de traits.'],
 freeze:['Freeze for the next round','Congele para a próxima rodada','Freeze this hand to preserve the third Warrior. Next setup keeps these cards and fills empty spaces up to 4. Freezing is free, never buys cards, and must be chosen again for each later round.','Congele esta mão para preservar o terceiro Warrior. O próximo preparo mantém estas cartas e preenche espaços até 4. Congelar é grátis, não paga pelas cartas e precisa ser escolhido novamente a cada rodada seguinte.'],
 fight2:['Test the frozen hand','Teste a mão congelada','Start the next battle. Your paid units remain between rounds and return at full health.','Comece a próxima batalha. Suas unidades pagas permanecem entre rodadas e voltam com vida cheia.'],
 watch2:['Wait for the next setup','Aguarde o próximo preparo','The hand is hidden during combat. Freeze is chosen only during setup. At 40 seconds damage increases ×5; at 120 seconds the round is a draw without points.','A mão fica oculta no combate. O congelamento é escolhido somente no preparo. Aos 40 segundos o dano aumenta ×5; aos 120 a rodada empata sem pontos.'],
 result2:['Return to your frozen cards','Volte às cartas congeladas','Prepare the next round to buy the third Warrior and complete the fusion.','Prepare a próxima rodada para comprar o terceiro Warrior e completar a fusão.'],
 fusion:['Pay for the third copy','Pague pela terceira cópia','Select Warrior in hand and place it in the highlighted reserve slot. Pay 2 energy: the two paid copies across field and reserve fuse automatically with this third one.','Selecione Warrior na mão e coloque na vaga destacada do banco. Pague 2 de energia: as duas cópias pagas no campo e banco se fundem automaticamente com a terceira.'],
 'fusion-done':['Three copies, one stronger unit','Três cópias, uma unidade mais forte','The fusion stays at Warrior’s field position and occupies one slot, improving stats and skill power by 75% over the copies’ average. It lasts only this encounter. Upgrades improve individual cards for the run and never reduce energy cost.','A fusão mantém a posição do Warrior no campo e ocupa uma vaga, aumentando atributos e poder da skill em 75% sobre a média das cópias. Dura só este confronto. Upgrades melhoram cartas individuais pela run e não reduzem o custo de energia.'],
 fight3:['Finish the encounter','Conclua o confronto','Start battle with your fused Warrior. Normal encounters require 3 round wins; the Boss requires 4. Losing an encounter ends the run.','Comece a batalha com Warrior fundido. Confrontos normais exigem 3 vitórias em rodadas; o Boss exige 4. Perder um confronto encerra a run.'],
 watch3:['Watch the fusion','Observe a fusão','Watch your stronger unit. You can pause or change the speed.','Observe sua unidade mais forte. Você pode pausar ou mudar a velocidade.'],
 result3:['One more round','Mais uma rodada','Prepare the next round and keep fighting until you win the encounter.','Prepare a próxima rodada e continue até vencer o confronto.'],
 complete:['Combat lesson complete','Etapa de combate concluída','You practiced dragging, energy refunds, refresh, deck inspection, freeze and fusion. Continue to learn the map and Relic Bag. New encounters reset formation, energy and fusion; recruited cards and upgrades remain for this run.','Você praticou arraste, devolução de energia, reciclagem, consulta do deck, congelamento e fusão. Continue para conhecer mapa e bolsa. Novos confrontos reiniciam formação, energia e fusão; cartas recrutadas e upgrades permanecem nesta run.']
});
const tutorialInfoSteps=['traits','energy','return-info','combat','removed','inspect-read','deck-read','piles-read','fusion-done','complete'];
let tutorialLastStep='',tutorialResizeFrame=0;
function tutorialTarget(step){const t=S?.tutorial;if(!t)return '';const extra={'remove-select':'[data-unit="'+t.reserve+'"]','remove-unit':'[data-act="remove"]',refresh:'[data-act="refresh-hand"]','inspect-select':'.hand [data-act="hand"]',inspect:'.selection [data-act="info"]',deck:'[data-act="deck"]',piles:'[data-act="piles"]','second-copy':'.hand [data-id="'+S.hand.find(id=>G.card(S,id)?.type==='warrior')+'"]',fusion:'.hand [data-id="'+S.hand.find(id=>G.card(S,id)?.type==='warrior')+'"]',fight2:'[data-act="fight"]',fight3:'[data-act="fight"]',result2:'[data-act="next-round"]',result3:'[data-act="next-round"]',watch2:'.battle-foot',watch3:'.battle-foot','drag-again':'[data-unit="'+t.reserve+'"]'};if(['second-copy','fusion'].includes(step)&&selected?.kind==='hand'&&G.card(S,selected.uid)?.type==='warrior')return '[data-act="bench-slot"][data-pos="0"]';if(step==='fusion-done')return '[data-unit="'+t.warrior+'"]';if(extra[step])return extra[step];const hand=id=>'[data-act="hand"][data-id="'+id+'"]';return ({'select-warrior':hand(t.warrior),'place-warrior':'[data-act="slot"][data-pos="10"]',traits:'.trait-ribbon','select-lancer':hand(t.lancer),'place-lancer':'[data-act="slot"][data-pos="11"]',energy:'.arena-status',fight:'[data-act="fight"]',combat:'#combat',speed:'.speed',watch:'.battle-foot',result:'[data-act="next-round"]','select-reserve':hand(t.reserve),'place-reserve':'[data-act="bench-slot"][data-pos="0"]','select-bench':'[data-act="bench-slot"][data-pos="0"]',transfer:'[data-act="slot"][data-pos="12"]',freeze:'[data-act="freeze-hand"]'})[step]||'';}
function tutorialAllowed(el,step){if(!el)return false;const a=el.dataset.act,t=S.tutorial;if(a?.startsWith('tutorial-'))return true;
 if(['inspect-read','deck-read','piles-read'].includes(step))return false;
 if(['fight2','fight3'].includes(step))return a==='fight';
 if(['watch2','watch3'].includes(step))return ['speed','pause'].includes(a);
 if(['result2','result3'].includes(step))return a==='next-round';
 if(step==='refresh')return a==='refresh-hand';
 if(step==='remove-select')return a==='slot'&&S.board[+el.dataset.pos]===t.reserve;
 if(step==='remove-unit')return a==='remove';
 if(step==='drag-again')return a==='slot';
 if(step==='inspect-select')return a==='hand';if(step==='inspect')return a==='info';
 if(step==='deck'||step==='piles')return a===step;
 if(['second-copy','fusion'].includes(step))return a==='hand'&&G.card(S,el.dataset.id)?.type==='warrior'||a==='bench-slot'&&+el.dataset.pos===0;

 if(['select-warrior','place-warrior'].includes(step))return a==='hand'&&el.dataset.id===t.warrior||a==='slot'&&+el.dataset.pos===10;
 if(['select-lancer','place-lancer'].includes(step))return a==='hand'&&el.dataset.id===t.lancer||a==='slot'&&+el.dataset.pos===11;
 if(['select-reserve','place-reserve'].includes(step))return a==='hand'&&el.dataset.id===t.reserve||a==='bench-slot'&&+el.dataset.pos===0;
 if(['select-bench','transfer'].includes(step))return a==='bench-slot'&&+el.dataset.pos===0||a==='slot'&&+el.dataset.pos===12;
 return step==='fight'&&a==='fight'||step==='speed'&&a==='speed'&&+el.dataset.speed>1||step==='watch'&&['speed','pause'].includes(a)||step==='result'&&a==='next-round'||step==='freeze'&&a==='freeze-hand';
}
function tutorialClear(){document.getElementById('tutorial-coach')?.remove();document.querySelectorAll('.tutorial-target').forEach(el=>el.classList.remove('tutorial-target'));tutorialLastStep='';}
function tutorialPosition(){const root=$('tutorial-coach');if(!root)return;const step=S?.tutorial?.step,target=document.querySelector(root.dataset.target||tutorialTarget(step)||'.no-tutorial-target'),spot=root.querySelector('.tutorial-spot'),panel=root.querySelector('.tutorial-panel');if(!panel)return;const app=$('app').getBoundingClientRect(),width=Math.min(440,window.innerWidth-20,app.width-16);panel.style.width=width+'px';panel.style.left=Math.max(10,app.left+(app.width-width)/2)+'px';panel.style.top='';panel.style.bottom='';if(target){const r=target.getBoundingClientRect();spot.hidden=false;Object.assign(spot.style,{left:r.left-4+'px',top:r.top-4+'px',width:r.width+8+'px',height:r.height+8+'px'});if(r.top>window.innerHeight*.48)panel.style.top=Math.max(80,app.top+80)+'px';else panel.style.bottom='12px';}else{spot.hidden=true;panel.style.bottom='12px';}}
function tutorialRefresh(){if(TutorialFlow.active(S)&&$('app').querySelector('.arena-shell,.result-score')&&!$('overlay')){if(S.tutorial.step==='inspect-read')openDetail(S.hand[0],'run');if(S.tutorial.step==='deck-read')deckModal();if(S.tutorial.step==='piles-read')tutorialPiles();}if(!TutorialFlow.active(S)){tutorialClear();tutorialFusionTip();return;}if(!$('app').querySelector('.arena-shell,.result-score')){tutorialClear();return;}const before=S.tutorial.step,step=TutorialFlow.reconcile(S,selected);if(!step)return;
 if(step==='combat'&&battle&&!battle.result){paused=true;paintPause();}
 if(before!==step)save();const old=$('tutorial-coach');if(tutorialLastStep===step&&old){document.querySelectorAll('.tutorial-target').forEach(el=>el.classList.remove('tutorial-target'));document.querySelector(tutorialTarget(step)||'.no-tutorial-target')?.classList.add('tutorial-target');tutorialPosition();return;}old?.remove();document.querySelectorAll('.tutorial-target').forEach(el=>el.classList.remove('tutorial-target'));const target=document.querySelector(tutorialTarget(step)||'.no-tutorial-target');target?.classList.add('tutorial-target');const text=false?['Tutorial complete','Tutorial concluído','You can return to your journey. The First Steps milestone and its borrowed decks are already unlocked.','Você já pode voltar à jornada. O milestone Primeiros passos e seus baralhos emprestados já estão liberados.']:TutorialText[step]||TutorialText.complete;const root=document.createElement('div');root.id='tutorial-coach';root.innerHTML='<div class="tutorial-spot" aria-hidden="true"></div><section class="tutorial-panel" role="region" aria-label="'+L('Interactive tutorial','Tutorial interativo')+'"><div class="tutorial-top"><span>'+L('TUTORIAL','TUTORIAL')+'</span><button data-act="tutorial-skip">'+L('Skip tutorial','Pular tutorial')+'</button></div><h2>'+L(text[0],text[1])+'</h2><p aria-live="polite">'+L(text[2],text[3])+'</p>'+(tutorialInfoSteps.includes(step)?'<button class="primary" data-act="tutorial-next">'+L(step==='complete'?'Finish tutorial':'Continue',step==='complete'?'Concluir tutorial':'Continuar')+'</button>':'')+'</section>';document.body.appendChild(root);tutorialLastStep=step;tutorialPosition();(root.querySelector('[data-act="tutorial-next"]')||target)?.focus({preventScroll:true});}
function tutorialFinish(){const newly=!Progress.profile.stats.firstSteps,replay=S.tutorialReplay,back=S.tutorialReturnState;S.tutorial.mode='completed';Progress.completeTutorial();tutorialClear();if(replay){cancelAnimationFrame(raf);battle=null;S=back?migrateRun(back):null;if(S?.tutorial?.mode==='guided')S.tutorial.mode='completed';selected=null;closeModal();save();if(S)render();else home();}else{save();render();}toast(newly?L('First Steps complete: two borrowed decks unlocked!','Primeiros passos concluído: dois baralhos emprestados liberados!'):L('Tutorial complete. Welcome back to your journey!','Tutorial concluído. De volta à sua jornada!'));}
function tutorialSkip(){const replay=S?.tutorialReplay,back=S?.tutorialReturnState;if(!S?.tutorial)return;S.tutorial.mode='skipped';tutorialClear();if(replay){cancelAnimationFrame(raf);battle=null;S=back?migrateRun(back):null;selected=null;closeModal();save();if(S)render();else home();return;}Progress.profile.onboarding.status='skipped';if(battle&&!battle.result){paused=false;last=performance.now();paintPause();}save();toast(L('Win your first encounter to unlock the other two borrowed decks.','Vença o primeiro confronto para liberar os outros dois baralhos emprestados.'));}
function tutorialReplay(){if(battle&&!battle.result)return;const back=S;closeModal();selected=null;battle=null;S=G.fresh('vanguard',73421);S.tutorialReplay=true;S.tutorialReturnState=back;S.tutorial={mode:'guided',step:'select-warrior'};const node=G.available(S).find(n=>n.type==='battle')||G.available(S)[0];G.enter(S,node.id);save();render();}
function tutorialFusionTip(){if(S?.phase!=='prep'||Progress.profile.onboarding.fusionSeen||S?.tutorialReplay||$('overlay')||!S.hand.some(id=>G.canFuse(S,id)))return;Progress.profile.onboarding.fusionSeen=true;save();openModal('<h2>'+L('A fusion opportunity','Uma oportunidade de fusão')+'</h2><p>'+L('You have two paid copies of a unit and a third in hand. Pay its energy cost to fuse automatically. Field and reserve count together; an existing field position is kept.','Você tem duas cópias pagas de uma unidade e a terceira na mão. Pague o custo de energia para fundir automaticamente. Campo e banco contam juntos; a posição existente no campo é mantida.')+'</p><button class="primary" data-act="close">'+L('Got it','Entendi')+'</button>');}
window.JourneyTutorial={allowDrop(target){return !TutorialFlow.active(S)||tutorialAllowed(target,TutorialFlow.reconcile(S,selected));},guard(e){const el=e.target.closest?.('[data-act]'),action=el?.dataset.act;if(e.type==='click'&&action==='tutorial-replay'){e.preventDefault();e.stopImmediatePropagation();tutorialReplay();return;}if(!TutorialFlow.active(S)||!$('app').querySelector('.arena-shell,.result-score'))return;const step=TutorialFlow.reconcile(S,selected);if(e.type==='keydown'&&!['Enter',' ','Escape'].includes(e.key))return;if(e.type==='keydown'&&e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();return;}
 if(!tutorialAllowed(el,step)){e.preventDefault();e.stopImmediatePropagation();return;}
 if(e.type==='click'&&action==='tutorial-skip'){e.preventDefault();e.stopImmediatePropagation();tutorialSkip();return;}
 if(e.type==='click'&&action==='tutorial-next'){e.preventDefault();e.stopImmediatePropagation();if(step==='complete')tutorialBeginMap();else{if(['inspect-read','deck-read','piles-read'].includes(step))closeModal();TutorialFlow.next(S);selected=null;save();tutorialRefresh();}return;}
 if(e.type==='click'&&step==='speed'&&action==='speed'){S.tutorial.step='watch';paused=false;last=performance.now();paintPause();save();}
 if(e.type==='click'&&['select-bench','transfer'].includes(step)&&action==='slot'){e.preventDefault();e.stopImmediatePropagation();return;}
 if(e.type==='click'&&action==='info'&&step==='inspect')S.tutorial.step='inspect-read';
 if(e.type==='click'&&action==='deck'&&step==='deck')S.tutorial.step='deck-read';
 if(e.type==='click'&&action==='piles'&&step==='piles')S.tutorial.step='piles-read';
 if(e.type==='click')queueMicrotask(tutorialRefresh);
}};
const tutorialOriginalShow=show;show=function(html){tutorialOriginalShow(html);queueMicrotask(tutorialRefresh);};
const tutorialOriginalDragFinish=finishRosterDrag;finishRosterDrag=function(held,e){const before=S?.board?.slice();tutorialOriginalDragFinish(held,e);if(TutorialFlow.active(S)&&e?.type==='pointerup'&&S.board.includes(S.tutorial.reserve)&&JSON.stringify(before)!==JSON.stringify(S.board))S.tutorial.dragged=true;queueMicrotask(tutorialRefresh);};
window.addEventListener('resize',()=>{cancelAnimationFrame(tutorialResizeFrame);tutorialResizeFrame=requestAnimationFrame(tutorialPosition);});window.visualViewport?.addEventListener('resize',tutorialPosition);

// Lessons after the encounter use the live map and the actual bag controls.
const JourneyTourPages=[
 ['Choose your route','Escolha seu caminho','Follow the golden connections. Each node is one stop; you cannot return to a skipped branch. Recruited cards and upgrades last this run.','Siga as conexões douradas. Cada nó é uma parada; não é possível voltar para um caminho ignorado. Cartas recrutadas e upgrades duram esta run.'],
 ['Battles on the map','Batalhas no mapa','Battle: a normal encounter. Elite: a stronger team with relics. Boss: the final encounter, first to 4 round wins. Losing any encounter ends the run.','Batalha: confronto normal. Elite: equipe mais forte, com relíquias. Boss: confronto final, vence quem ganhar 4 rodadas. Perder qualquer confronto encerra a run.',['battle','elite','boss']],
 ['Grow your team','Fortaleça sua equipe','Recruit: add a card to your deck. Upgrade: choose a card from your deck to improve its stats and strengthen its skill.','Recrutamento: adicione uma carta ao seu deck. Upgrade: escolha uma carta do deck para melhorar seus atributos e fortalecer sua habilidade.',['recruit','upgrade']],
 ['Other stops','Outras paradas','Shop: spend run gold on cards, relics and services. Event: read the reward and risk before choosing. Relic: choose a passive item and fit it into your bag.','Loja: gaste ouro da run em cartas, relíquias e serviços. Evento: leia a recompensa e o risco antes de escolher. Relíquia: escolha um item passivo e encaixe na bolsa.',['shop','event','relic']]
];
const BagLessonText={
 'bag-open':['Open your Relic Bag','Abra sua bolsa de relíquias','You earned a relic for completing your first encounter! Tap the highlighted star button on the map to open your bag.','Você ganhou uma relíquia ao concluir seu primeiro confronto! Toque no botão de estrela destacado no mapa para abrir a bolsa.','[data-act="artifacts"]'],
 'bag-new-select':['Your new relic','Sua nova relíquia','Select the relic you received. It is stored and inactive until you fit it into the bag.','Selecione a relíquia que você recebeu. Ela está guardada e fica inativa até ser encaixada na bolsa.',''],
 'bag-new-place':['Equip your reward','Equipe sua recompensa','Fit the new relic in the highlighted cell. Each relic needs enough free space for its shape.','Encaixe a nova relíquia na célula destacada. Cada relíquia precisa de espaço livre para seu formato.','[data-act="bag-cell"][data-pos="8"]'],
 'bag-select':['Select a relic','Selecione uma relíquia','The bag has 16 cells. Only fitted relics grant effects. Select your starting relic below the grid.','A bolsa tem 16 células. Só relíquias encaixadas concedem efeitos. Selecione sua relíquia inicial abaixo da grade.','.bag-item'],
 'bag-rotate':['Rotate the shape','Gire o formato','Tap Rotate to turn the selected relic before fitting it. Shapes cannot overlap or leave the grid.','Toque em Girar para rodar a relíquia antes de encaixar. Formatos não podem se sobrepor nem sair da grade.','[data-act="bag-rotate"]'],
 'bag-lift':['Move to storage','Mova para a reserva','Tap Store / move. This frees its cells, but the stored relic is inactive.','Toque em Guardar / mover. Isso libera as células, mas a relíquia guardada fica inativa.','[data-act="bag-lift"]'],
 'bag-place':['Fit it again','Encaixe novamente','Tap the highlighted cell: it is the top-left corner of the rotated shape. You can rearrange relics outside combat.','Toque na célula destacada: ela é o canto superior esquerdo do formato girado. Você pode reorganizar relíquias fora do combate.','[data-act="bag-cell"][data-pos="0"]'],
 'bag-confirm':['Activate your relic','Ative sua relíquia','Confirm the bag to apply the arrangement. A stored relic remains available but gives no bonus until fitted again.','Confirme a bolsa para aplicar a organização. Uma relíquia guardada continua disponível, mas não dá bônus até ser encaixada novamente.','[data-act="bag-apply"]'],
 'bag-done':['Ready for the journey','Pronto para a jornada','Combat, map and bag lessons are complete. Finish to return to the journey. You can replay this tutorial from How to Play.','As etapas de combate, mapa e bolsa estão concluídas. Conclua para voltar à jornada. Você pode refazer o tutorial em Como jogar.','']
};
// Explanations are a catalog; the displayed menu determines the tour order.
const MenuTourPages=[
 ['Between journeys','Entre jornadas','Gold belongs to the current run. Diamonds and permanent unlocks remain after a win or defeat. Borrowed decks can be played without owning their cards.','O ouro pertence à run atual. Diamantes e desbloqueios permanentes ficam após vitória ou derrota. Decks emprestados podem ser usados sem possuir suas cartas.','[data-act="new"]'],
 ['Continue the journey','Continuar a jornada','Resume your saved run from where you stopped. Starting another run ends the current journey.','Retome a run salva de onde parou. Iniciar outra run encerra a jornada atual.','[data-act="continue"]'],
 ['Training','Treinamento','Try decks, upgrades and opponents freely, without spending resources or changing your current run. Training gives no progression rewards.','Teste decks, melhorias e adversários livremente, sem gastar recursos nem alterar sua run atual. O treino não concede recompensas de progressão.','[data-act="training-config"]'],
 ['Skill Tree','Árvore de habilidades','Use permanent levels to choose bonuses for future journeys. Open the tree to review your level, points and reset options.','Use níveis permanentes para escolher bônus para as próximas jornadas. Abra a árvore para consultar nível, pontos e opções de reset.','[data-act="tree-open"]'],
 ['Journey Advantages','Vantagens da Jornada','After your first complete run victory, use Insignia earned at new challenge levels to activate advantages. You can deactivate them and recover the Insignia.','Após a primeira vitória em uma run completa, use Insígnias obtidas em níveis inéditos de desafio para ativar vantagens. Você pode desativá-las e recuperar as Insígnias.','[data-act="cp2-advantages"]'],
 ['Finish opening your booster','Concluir abertura do booster','Return to the booster you already opened to reveal its remaining cards. This does not buy another booster.','Retorne ao booster já aberto para revelar as cartas restantes. Isso não compra outro booster.','[data-act="pack-resume"]'],
 ['Permanent shop','Loja permanente','Spend diamonds on available boosters, collection cards and relics. Purchases here affect permanent progress; the shops on the map use run gold.','Use diamantes para comprar boosters, cartas e relíquias disponíveis para a coleção. Aqui as compras afetam o progresso permanente; lojas do mapa usam ouro da run.','[data-act="meta-shop"]'],
 ['Collection','Coleção','Browse what you own and what you have discovered. Run recruits do not automatically become permanent collection copies.','Consulte o que você possui e o que já descobriu. Recrutas da run não viram automaticamente cópias da coleção permanente.','[data-act="meta-collection"]'],
 ['Custom decks','Decks customizados','Build a 20-card deck using the copies you own, up to 4 of each character, and choose an owned starting relic. Borrowed decks are separate.','Monte um deck de 20 cartas com as cópias que possui, até 4 de cada personagem, e escolha uma relíquia inicial própria. Decks emprestados são separados.','[data-act="meta-custom"]'],
 ['Milestones','Milestones','Complete objectives to unlock rewards and more options. First Steps unlocks the other two starting borrowed decks. Check each objective and its reward here.','Cumpra objetivos para liberar recompensas e mais opções. Primeiros passos libera os outros dois decks emprestados iniciais. Confira aqui cada objetivo e recompensa.','[data-act="meta-milestones"]'],
 ['Profile and save','Perfil e save','Review your results in Profile. Progress is saved in this browser; export a backup and import it to continue on another device.','Consulte seus resultados em Perfil. O progresso é salvo neste navegador; exporte um backup e importe para continuar em outro aparelho.','[data-act="meta-profile"]']
];
function menuTourPages(){return [...$('app').querySelectorAll('.home-buttons [data-act]')].map(el=>MenuTourPages.find(page=>el.matches(page[4]))).filter(Boolean);}
function tutorialBeginMap(){cancelAnimationFrame(raf);battle=null;selected=null;closeModal();if(S.phase==='encounterWin')G.leave(S);TutorialFlow.grantRelic(S);S.tutorial.step='map-0';save();render();}
function tutorialTourPanel(text,target='',next=true){tutorialClear();const root=document.createElement('div');root.id='tutorial-coach';root.innerHTML='<div class="tutorial-spot" hidden></div><section class="tutorial-panel" role="region" aria-label="'+L('Journey tutorial','Tutorial da jornada')+'"><div class="tutorial-top"><span>TUTORIAL</span><button data-act="tutorial-skip">'+L('Skip','Pular')+'</button></div><h2>'+L(text[0],text[1])+'</h2><p>'+L(text[2],text[3])+'</p>'+(Array.isArray(text[4])?'<div class="tutorial-map-icons">'+text[4].map(type=>'<span>'+Icon(mapIcon(type))+I18n.t(mapType(type))+'</span>').join('')+'</div>':'')+(next?'<button class="primary" data-act="tutorial-tour-next">'+L('Continue','Continuar')+'</button>':'')+'</section>';root.dataset.target=target;document.body.appendChild(root);const el=target?document.querySelector(target):null;el?.classList.add('tutorial-target');if(el){const r=el.getBoundingClientRect();if(r.top<80||r.bottom>innerHeight-10){el.scrollIntoView({block:'center'});globalThis.JourneyMenuScroll?.capture(true);}}tutorialPosition();if(el){const r=el.getBoundingClientRect(),spot=root.querySelector('.tutorial-spot'),panel=root.querySelector('.tutorial-panel');spot.hidden=false;Object.assign(spot.style,{left:r.left-4+'px',top:r.top-4+'px',width:r.width+8+'px',height:r.height+8+'px'});if(r.top>innerHeight*.5){panel.style.bottom='';panel.style.top='85px';}else{panel.style.top='';panel.style.bottom='12px';}}}
let menuTourIndex=null,menuTourSequence=[];
const tutorialBaseRefresh=tutorialRefresh;
tutorialRefresh=function(){const step=S?.tutorial?.step;
 if(menuTourIndex!==null){tutorialTourPanel(menuTourSequence[menuTourIndex],menuTourSequence[menuTourIndex][4]);return;}
 if(TutorialFlow.active(S)&&$('app').querySelector('.journey-map-screen')&&step?.startsWith('map-')){tutorialTourPanel(JourneyTourPages[+step.slice(4)]);return;}
 if(TutorialFlow.active(S)&&$('app').querySelector('.journey-map-screen')&&step?.startsWith('bag-')){TutorialFlow.grantRelic(S);if(step!=='bag-open'&&step!=='bag-done'&&!document.querySelector('.bag-modal')){S.tutorial.step='bag-select';bagView();}const t=BagLessonText[S.tutorial.step];let target=t[4];if(S.tutorial.step==='bag-select')target='[data-act="bag-select"][data-key="'+bagDraft?.find(it=>it.id!==S.tutorial.rewardRelic)?.key+'"]';if(S.tutorial.step==='bag-new-select')target='[data-act="bag-select"][data-key="'+bagDraft?.find(it=>it.id===S.tutorial.rewardRelic)?.key+'"]';tutorialTourPanel(t,target,S.tutorial.step==='bag-done');return;}
 tutorialBaseRefresh();
};
const tutorialBaseGuard=window.JourneyTutorial.guard;
window.JourneyTutorial.guard=function(e){const el=e.target.closest?.('[data-act]'),action=el?.dataset.act,step=S?.tutorial?.step;
 const stop=()=>{e.preventDefault();e.stopImmediatePropagation();};
 if(menuTourIndex!==null){if(!['tutorial-skip','tutorial-tour-next'].includes(action)){stop();return;}if(e.type==='click'){stop();if(action==='tutorial-skip'||++menuTourIndex>=menuTourSequence.length){menuTourIndex=null;Progress.profile.onboarding.menuSeen=true;tutorialClear();save();}else tutorialRefresh();}return;}
 if(TutorialFlow.active(S)&&$('app').querySelector('.journey-map-screen')&&(step?.startsWith('map-')||step?.startsWith('bag-'))){
  if(action==='tutorial-skip'){if(e.type==='click'){stop();closeModal();bagDraft=null;tutorialSkip();}return;}
  if(action==='tutorial-tour-next'){if(e.type==='click'){stop();if(step==='bag-done'){tutorialFinish();return;}const page=+step.slice(4)+1;if(page<JourneyTourPages.length)S.tutorial.step='map-'+page;else{TutorialFlow.grantRelic(S);S.tutorial.step='bag-open';}save();tutorialRefresh();}return;}
  if(step==='bag-open'){if(action!=='artifacts'){stop();return;}if(e.type==='click'){stop();TutorialFlow.grantRelic(S);S.tutorial.step='bag-select';bagView();save();tutorialRefresh();}return;}
  const expected={'bag-new-select':'bag-select','bag-new-place':'bag-cell','bag-select':'bag-select','bag-rotate':'bag-rotate','bag-lift':'bag-lift','bag-place':'bag-cell','bag-confirm':'bag-apply'}[step];
  if(!expected||action!==expected||step==='bag-place'&&el.dataset.pos!=='0'||step==='bag-new-place'&&el.dataset.pos!=='8'||step==='bag-select'&&bagDraft?.find(it=>it.key===el.dataset.key)?.id===S.tutorial.rewardRelic||step==='bag-new-select'&&bagDraft?.find(it=>it.key===el.dataset.key)?.id!==S.tutorial.rewardRelic){stop();return;}
  if(e.type==='click'){S.tutorial.step={'bag-select':'bag-rotate','bag-rotate':'bag-lift','bag-lift':'bag-place','bag-place':'bag-new-select','bag-new-select':'bag-new-place','bag-new-place':'bag-confirm','bag-confirm':'bag-done'}[step];queueMicrotask(()=>{save();tutorialRefresh();});}return;
 }
 tutorialBaseGuard(e);
 // Replace the generic cycle description with complete counts, also outside lessons.
 if(!e.defaultPrevented&&e.type==='click'&&action==='piles'&&S){stop();tutorialPiles();tutorialRefresh();}
};
const tutorialBaseHome=home;home=function(){tutorialBaseHome();if(Progress.profile.stats.runs>0&&!Progress.profile.onboarding.menuSeen&&!S?.tutorialReplay){menuTourSequence=menuTourPages();if(menuTourSequence.length){menuTourIndex=0;queueMicrotask(tutorialRefresh);}}};

function tutorialPiles(){openModal('<h2>'+L('Card cycle','Ciclo das cartas')+'</h2><div class="run-summary cycle-summary">'+[[S.cards.length,L('run deck','deck da run')],[S.draw.length,L('draw pile','compra')],[S.discard.length,L('discard pile','descarte')],[S.hand.length,L('hand','mão')],[[...S.board,...S.bench].filter(Boolean).reduce((n,id)=>n+(S.fusions?.[id]?.length||1),0),L('bound cards','cartas vinculadas')]].map(([n,label])=>'<div><b>'+n+'</b><span>'+label+'</span></div>').join('')+'</div><p>'+L('The run deck total includes every pile. When draw runs out, discard is shuffled. Field, reserve and fused copies stay bound. Freeze during setup preserves the remaining hand for the next round and draws only to fill it to 4.','O total do deck inclui todas as pilhas. Quando a compra acaba, o descarte é reembaralhado. Campo, banco e cópias fundidas ficam vinculados. Congelar no preparo preserva o restante da mão para a próxima rodada e compra apenas para completar 4.')+'</p>');}

// Keep the spotlight aligned with live bounds, including modal entrance animation.
let tutorialTrackFrame=0;
function tutorialTrack(){const coach=$('tutorial-coach');if(coach){tutorialPosition();tutorialTrackFrame=requestAnimationFrame(tutorialTrack);}else tutorialTrackFrame=0;}
new MutationObserver(()=>{if($('tutorial-coach')&&!tutorialTrackFrame)tutorialTrackFrame=requestAnimationFrame(tutorialTrack);}).observe(document.body,{childList:true});
let tutorialWatchKey='',tutorialWatchUntil=0;
const tutorialV29Refresh=tutorialRefresh;
tutorialRefresh=function(){tutorialV29Refresh();const step=S?.tutorial?.step;if(!TutorialFlow.active(S)||S.phase!=='battle'||!['watch','watch2','watch3'].includes(step)){tutorialWatchKey='';return;}const key=S.battleSerial+':'+S.round+':'+step;if(key!==tutorialWatchKey){tutorialWatchKey=key;tutorialWatchUntil=Date.now()+3000;setTimeout(()=>{if(tutorialWatchKey===key)tutorialRefresh();},3005);}if(Date.now()>=tutorialWatchUntil){$('tutorial-coach')?.remove();document.querySelectorAll('.tutorial-target').forEach(el=>el.classList.remove('tutorial-target'));}};
